      fr: { question: "Qui fut le premier empereur à unifier la Chine sous une seule autorité en 221 av. J.-C. ?", options: ["L’empereur Wu des Han", "Qin Shi Huang", "L’empereur Yao", "Liu Bang"], explanation: "Qin Shi Huang, roi de l’État de Qin, unifia les États chinois en guerre en 221 av. J.-C., devenant le premier empereur d’une Chine unifiée. Il normalisa les poids, les mesures, la monnaie et l’écriture dans tout l’empire." },
      es: { question: '¿Quién fue el primer emperador en unificar China bajo un solo gobierno en 221 a.C.?', options: ['Emperador Wu de Han', 'Qin Shi Huang', 'Emperador Yao', 'Liu Bang'], explanation: 'Qin Shi Huang, el rey del estado de Qin, unificó los estados chinos en guerra en 221 a.C. Estandarizó pesos, medidas, moneda y escritura en todo el imperio.' },
