export function getQuestionsForTopic(topicId: string): TerritoryQuizQuestion[] {
  return TERRITORY_QUIZ_BANK.filter(q => q.topicId === topicId);
}

export function getTranslatedTerritoryQuestion(
  q: TerritoryQuizQuestion,
  lang: Language
): { question: string; options: string[]; explanation: string } {
  if (lang === 'en' || !q.i18n[lang as ContentLang]) {
    return { question: q.question, options: q.options, explanation: q.explanation };
  }
  const t = q.i18n[lang as ContentLang]!;
  return { question: t.question, options: t.options, explanation: t.explanation };
}
